#import <IOKit/hid/IOHIDLib.h>
#import <IOKit/IOKitLib.h>
#import <Foundation/Foundation.h>

void sendTouchEvent(int x, int y) {
    IOHIDManagerRef manager = IOHIDManagerCreate(kCFAllocatorDefault, kIOHIDOptionsTypeNone);

    IOHIDManagerSetDeviceMatching(manager, NULL);
    IOHIDManagerOpen(manager, kIOHIDOptionsTypeNone);

    CFSetRef devices = IOHIDManagerCopyDevices(manager);

    if (devices && CFSetGetCount(devices) > 0) {
        const void **devArray = malloc(sizeof(void *) * CFSetGetCount(devices));
        CFSetGetValues(devices, devArray);

        IOHIDDeviceRef device = (IOHIDDeviceRef)devArray[0];

        // Create a simple HID report to simulate touch
        uint8_t report[32] = {0};
        report[0] = 0x01; // Touch report ID

        // X coordinate (little endian)
        report[1] = x & 0xFF;
        report[2] = (x >> 8) & 0xFF;

        // Y coordinate (little endian)  
        report[3] = y & 0xFF;
        report[4] = (y >> 8) & 0xFF;

        // Try to write the report
        IOReturn ret = IOHIDDeviceSetReport(device, kIOHIDReportTypeOutput, 0, report, 32);

        if (ret == kIOReturnSuccess) {
            printf("Touch event sent successfully!\n");
        } else {
            printf("Failed to send touch event: 0x%08x\n", ret);
        }

        free(devArray);
    }

    if (devices) CFRelease(devices);
    CFRelease(manager);
}

int main() {
    @autoreleasepool {
        printf("Sending touch event to coordinates (412, 785)\n");
        sendTouchEvent(412, 785);
    }
    return 0;
}
