                IOHIDElementRef xElement = NULL, yElement = NULL, buttonElement = NULL;

                for (CFIndex j = 0; j < CFArrayGetCount(elements); j++) {
                    IOHIDElementRef element = (IOHIDElementRef)CFArrayGetValueAtIndex(elements, j);
                    uint32_t usagePage = IOHIDElementGetUsagePage(element);
                    uint32_t usage = IOHIDElementGetUsage(element);

                    if (usagePage == 0x0001) { // Generic Desktop Page
                        if (usage == 0x0030) xElement = element;      // X
                        if (usage == 0x0031) yElement = element;      // Y
                        if (usage == 0x0090) buttonElement = element; // Button
                    }
                }

                if (xElement && yElement && buttonElement) {
                    printf("Found X, Y, and button elements\n");

                    // Send button down
                    IOHIDValueRef buttonValue = IOHIDValueCreateWithIntegerValue(kCFAllocatorDefault, buttonElement, mach_absolute_time(), 1);
                    IOHIDDeviceSetValue(device, buttonElement, buttonValue);
                    CFRelease(buttonValue);
                    printf("Button down\n");

                    [NSThread sleepForTimeInterval:0.1];

                    // Send button up
                    buttonValue = IOHIDValueCreateWithIntegerValue(kCFAllocatorDefault, buttonElement, mach_absolute_time(), 0);
                    IOHIDDeviceSetValue(device, buttonElement, buttonValue);
                    CFRelease(buttonValue);
                    printf("Button up\n");
                } else {
                    printf("Could not find required trackpad elements\n");
                }

                CFRelease(elements);
            }
            break;
        }
    }

    free(devArray);
    CFRelease(devices);
    CFRelease(manager);
}

int main() {
    @autoreleasepool {
        printf("Sending trackpad tap at (412, 785)...\n");
        sendTrackpadTap(412, 785);
        printf("Done\n");
    }
    return 0;
}
