#import <IOKit/hid/IOHIDLib.h>
#import <IOKit/IOKitLib.h>
#import <Foundation/Foundation.h>
#import <mach/mach_time.h>

void sendTrackpadClick() {
    IOHIDManagerRef manager = IOHIDManagerCreate(kCFAllocatorDefault, kIOHIDOptionsTypeNone);
    IOHIDManagerSetDeviceMatching(manager, NULL);
    IOHIDManagerOpen(manager, kIOHIDOptionsTypeNone);

    CFSetRef devices = IOHIDManagerCopyDevices(manager);
    if (!devices) {
        CFRelease(manager);
        return;
    }

    CFIndex count = CFSetGetCount(devices);
    const void **devArray = malloc(sizeof(void *) * count);
    CFSetGetValues(devices, devArray);

    for (CFIndex i = 0; i < count; i++) {
        IOHIDDeviceRef device = (IOHIDDeviceRef)devArray[i];
        CFStringRef product = IOHIDDeviceGetProperty(device, CFSTR(kIOHIDProductKey));

        if (product && CFStringCompare(product, CFSTR("Apple Internal Keyboard / Trackpad"), 0) == kCFCompareEqualTo) {
            CFArrayRef elements = IOHIDDeviceCopyMatchingElements(device, NULL, kIOHIDOptionsTypeNone);
            if (elements && CFArrayGetCount(elements) > 0) {
                // Use the first element (MultiTouch)
                IOHIDElementRef element = (IOHIDElementRef)CFArrayGetValueAtIndex(elements, 0);

                // Try to send a click event
                IOHIDValueRef value = IOHIDValueCreateWithIntegerValue(kCFAllocatorDefault, element, mach_absolute_time(), 1);
                if (value) {
                    IOReturn ret = IOHIDDeviceSetValue(device, element, value);
                    printf("Set device value: 0x%08x\n", ret);
                    CFRelease(value);

                    [NSThread sleepForTimeInterval:0.1];

                    value = IOHIDValueCreateWithIntegerValue(kCFAllocatorDefault, element, mach_absolute_time(), 0);
                    ret = IOHIDDeviceSetValue(device, element, value);
                    printf("Release value: 0x%08x\n", ret);
                    CFRelease(value);
                }

                CFRelease(elements);
            }
            break;
        }
    }

    free(devArray);
    CFRelease(devices);
    CFRelease(manager);
}

